Pattern wordNumber = Pattern.compile('([A-Za-z]+)-(\\d+)');
Matcher matcher = wordNumber.matcher('abc-123 xyz-456');
System.assert(matcher.find());
System.assertEquals('abc-123', matcher.group());
System.assertEquals('abc', matcher.group(1));
System.assertEquals(2, matcher.groupCount());
System.assertEquals(0, matcher.start());
System.assertEquals(0, matcher.start(1));
System.assertEquals(7, matcher.end());
System.assertEquals(3, matcher.end(1));
System.assert(matcher.find(8));
System.assertEquals('xyz-456', matcher.group());
matcher.reset();
System.assert(matcher.find());
matcher.reset('none');
System.assert(!matcher.find());
Matcher region = Pattern.compile('[a-z]+').matcher('123 abc 456');
System.assertEquals(region, region.region(4, 7));
System.assertEquals(4, region.regionStart());
System.assertEquals(7, region.regionEnd());
System.assert(region.lookingAt());
System.assert(region.matches());
System.assert(region.hasAnchoringBounds());
System.assert(!region.hasTransparentBounds());
System.assertEquals(region, region.useAnchoringBounds(false));
System.assert(!region.hasAnchoringBounds());
System.assertEquals(region, region.useTransparentBounds(true));
System.assert(region.hasTransparentBounds());
System.assertEquals('[a-z]+', region.pattern().pattern());
System.assertEquals(region, region.usePattern(Pattern.compile('\\d+')));
region.reset('99 bottles');
System.assert(region.find());
System.assertEquals('99', region.group());
System.assertEquals('a# b#', Pattern.compile('\\d+').matcher('a1 b22').replaceAll('#'));
System.assertEquals('a# b22', Pattern.compile('\\d+').matcher('a1 b22').replaceFirst('#'));
System.assert(System.Matcher.quoteReplacement('$1').contains('$1'));
Matcher tail = Pattern.compile('z').matcher('abc');
System.assert(!tail.find());
System.assert(!tail.hitEnd());
System.assert(!tail.requireEnd());

